create or replace function public.ensure_global_ui_label(p_key text, p_eng text) returns public.global_ui_labels language plpgsql security definer set search_path=public as $$ declare result public.global_ui_labels; begin if p_key is null or btrim(p_key)='' or p_eng is null or btrim(p_eng)='' then raise exception 'key and English label are required'; end if; insert into public.global_ui_labels(key,eng,bng) values (btrim(p_key),btrim(p_eng),null) on conflict (key) do nothing returning * into result; if result.key is null then select * into result from public.global_ui_labels where key=btrim(p_key); end if; return result; end; $$; revoke all on function public.ensure_global_ui_label(text,text) from public; grant execute on function public.ensure_global_ui_label(text,text) to anon, authenticated;